import api from '../../services/api';
export default {
  name: 'StoreFeaturesManagement',
  data() {
    return {
      features: [],
      featureFlags: {},
      labels: {
        products: 'Products',
        orders: 'Orders',
        inventory: 'Inventory',
        customers: 'Customers',
        reports: 'Reports',
        cashflow: 'Cash Flow',
        cashflow2: 'Cash Flow 2',
        forecasting: 'Forecasting',
        logistics: 'Delivery Service',
        notifications: 'Notifications',
        pos: 'POS'
      }
    };
  },
  async created() {
    await this.loadFeatures();
  },
  methods: {
    async loadFeatures() {
      try {
        const {
          data
        } = await api.get('/store/features/me');
        this.featureFlags = data?.features || {};
        this.features = Object.keys(this.featureFlags);
      } catch (err) {
        console.error(err);
        this.featureFlags = {};
        this.features = [];
      }
    },
    isEnabled(featureKey) {
      return this.featureFlags[featureKey] !== false;
    },
    async toggleFeature(featureKey) {
      const nextEnabled = !this.isEnabled(featureKey);
      try {
        await api.put('/store/features/me', {
          feature_key: featureKey,
          enabled: nextEnabled
        });
        this.featureFlags[featureKey] = nextEnabled;
      } catch (err) {
        alert('Failed to update feature');
      }
    }
  }
};
